INSERT INTO `courses` (`id`, `course_name`, `image`, `modules`, `duration`, `months`, `description`, `course_description`, `status`, `code`, `bundle_courses`) VALUES
(2, 'International Diploma in Information Technology', NULL, NULL, 8, NULL, '', 'This comprehensive program is designed to provide learners with a strong foundation in Information Technology, Software Development, and Digital Systems, while developing practical, industry-relevant skills. The course combines theoretical knowledge with hands-on experience to prepare students for entry-level IT roles, further academic studies, or professional growth in the technology sector.\r\n\r\nStudents will gain essential computing knowledge, programming skills, web development expertise, cybersecurity awareness, data analysis fundamentals, and professional workplace competencies. The program concludes with a Final Project, allowing learners to apply their skills to a real-world problem', 'Active', 'IDIT/1', NULL),
(3, 'Diploma in English', NULL, NULL, 8, NULL, 'This course strengthens essential English language skills, focusing on confident speaking, grammar accuracy, reading and listening comprehension, practical writing, and effective workplace communication.', 'This English Fundamentals course is designed to develop studentsâ€™ overall proficiency in the English language for academic, professional, and everyday communication. The course focuses on building strong foundations in speaking, listening, reading, and writing, while emphasizing correct grammar usage and effective workplace communication.\r\n\r\nStudents will improve their ability to speak confidently and fluently in a variety of situations, enhance their understanding of grammatical structures, and develop strong reading and listening comprehension skills. The course also places special emphasis on practical writing, including emails, reports, and basic professional documents. By the end of the course, learners will be well-prepared to communicate clearly and effectively in academic and workplace environments.', 'Active', 'DIE/1', NULL),
(4, 'Bundle', NULL, NULL, 8, NULL, 'This bundle combines a Diploma in English and an International Diploma in Information Technology, equipping students with strong communication skills and practical IT expertise for academic and professional success.', 'This academic bundle combines a Diploma in English with an International Diploma in Information Technology, equipping students with strong communication skills and in-demand technical knowledge.\r\n\r\nThe English diploma focuses on confident speaking, grammar, reading and listening skills, practical writing, and effective workplace communication. The IT diploma provides a solid foundation in computing, software development, cybersecurity, web and cloud technologies, multimedia, data science, and artificial intelligence, with programming in Python, Java, and C#. The program concludes with a Final Project to apply skills in real-world scenarios.\r\n\r\nThis bundle is ideal for students seeking a balanced qualification for employment or further studies in the global IT industry.', 'Active', 'IDIT/DIE-1', NULL),
(5, 'Foundation IT', NULL, NULL, 6, NULL, 'This course introduces essential IT concepts, covering computing fundamentals, hardware, networking, cybersecurity, web design, cloud technologies, and multimedia skills.', 'The Foundation IT course provides learners with essential knowledge and practical skills in information technology. It is designed for beginners who wish to build a strong understanding of modern computing and digital systems.\r\n\r\nThe course covers core areas such as computing fundamentals, office productivity tools, computer hardware and system architecture, networking and cybersecurity, web design and front-end development, cloud and internet technologies, and multimedia systems. Through hands-on learning and practical exercises, students develop technical skills, problem-solving abilities, and digital literacy required for further IT studies or entry-level roles in the IT field.', 'Active', 'FIT', NULL),
(6, 'Certificate In English', NULL, NULL, 6, NULL, '', '', 'Active', 'CIE', NULL),
(7, 'Professional Multimedia design and development', NULL, NULL, 8, NULL, 'This course trains students in professional graphic design, 3D modeling, video editing, motion graphics, and audio production using industry-standard creative software.', 'This course provides comprehensive training in industry-standard graphic design, multimedia, and digital content creation tools. Students will gain practical, hands-on experience using leading software applications for graphic design, illustration, publishing, 3D modeling, animation, and audio-video production.\r\n\r\nThe course covers image editing, vector illustration, layout and publication design, 3D modeling and animation, video editing, motion graphics, and audio production. Learners will develop creative, technical, and problem-solving skills required for careers in graphic design, multimedia production, advertising, digital marketing, and content creation. By the end of the course, students will be able to create professional-quality visual and multimedia projects for print, web, and digital platforms.', 'Active', 'PMDD', NULL),
(9, 'Diploma in Business Management', NULL, NULL, 8, NULL, '', '', 'Active', 'DIBM', NULL),
(10, 'Bundle  Foundation', NULL, NULL, 6, NULL, '', '', 'Active', 'FIT/DIE-1', NULL),
(11, 'Graphic Design', NULL, NULL, 4, NULL, '', '', 'Active', 'GD', NULL),
(12, 'Certificate in Office and Digital Skills', NULL, NULL, 3, NULL, '', '', 'Active', 'MSO', NULL),
(14, 'Bundle MULIT/DIE', NULL, NULL, 8, NULL, '', '', 'Active', 'MULIT/DIE', NULL);
