INSERT INTO `lms_ai_mcq_drafts` (`id`, `created_by_role`, `created_by_id`, `course_id`, `module_id`, `title`, `source_text`, `mcq_json`, `created_at`) VALUES
(1, 'admin', 6, NULL, NULL, 'Software', 'Source Text:\r\nSoftware is a collection of programs, data, and instructions that tell a computer what to do. System software manages hardware and application software helps users perform tasks.', '[\n    {\n        \"question\": \"What is software defined as?\",\n        \"options\": {\n            \"A\": \"Physical components of a computer\",\n            \"B\": \"A collection of programs, data, and instructions\",\n            \"C\": \"The electrical power supply for a computer\",\n            \"D\": \"A single, unchangeable instruction set\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"Software is a collection of programs, data, and instructions that tell a computer what to do.\"\n    },\n    {\n        \"question\": \"What is the primary function of software?\",\n        \"options\": {\n            \"A\": \"To physically connect computer components\",\n            \"B\": \"To generate electrical signals\",\n            \"C\": \"To tell a computer what actions to perform\",\n            \"D\": \"To store user files permanently\"\n        },\n        \"correct\": \"C\",\n        \"explanation\": \"Software\'s main role is to tell a computer what to do.\"\n    },\n    {\n        \"question\": \"Which of the following is NOT explicitly mentioned as a component of software in its definition?\",\n        \"options\": {\n            \"A\": \"Programs\",\n            \"B\": \"Data\",\n            \"C\": \"Instructions\",\n            \"D\": \"Hardware\"\n        },\n        \"correct\": \"D\",\n        \"explanation\": \"Software consists of programs, data, and instructions; hardware refers to physical components.\"\n    },\n    {\n        \"question\": \"What is the main role of system software?\",\n        \"options\": {\n            \"A\": \"To help users perform specific tasks\",\n            \"B\": \"To manage the computer\'s hardware and application software\",\n            \"C\": \"To create new programming languages\",\n            \"D\": \"To provide internet connectivity\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"System software manages hardware and application software.\"\n    },\n    {\n        \"question\": \"What is the main purpose of application software?\",\n        \"options\": {\n            \"A\": \"To manage internal system processes\",\n            \"B\": \"To help users accomplish specific tasks\",\n            \"C\": \"To control the computer\'s power supply\",\n            \"D\": \"To update the operating system automatically\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"Application software helps users perform tasks.\"\n    },\n    {\n        \"question\": \"Which type of software is responsible for managing the computer\'s hardware?\",\n        \"options\": {\n            \"A\": \"Application software\",\n            \"B\": \"Utility software\",\n            \"C\": \"System software\",\n            \"D\": \"Productivity software\"\n        },\n        \"correct\": \"C\",\n        \"explanation\": \"System software manages hardware.\"\n    },\n    {\n        \"question\": \"Software designed to help users perform specific tasks is known as what?\",\n        \"options\": {\n            \"A\": \"System software\",\n            \"B\": \"Firmware\",\n            \"C\": \"Application software\",\n            \"D\": \"Operating software\"\n        },\n        \"correct\": \"C\",\n        \"explanation\": \"Application software helps users perform tasks.\"\n    },\n    {\n        \"question\": \"According to the source, software consists of programs, data, and what else?\",\n        \"options\": {\n            \"A\": \"Electrical circuits\",\n            \"B\": \"User interfaces\",\n            \"C\": \"Instructions\",\n            \"D\": \"Physical memory\"\n        },\n        \"correct\": \"C\",\n        \"explanation\": \"Software is a collection of programs, data, and instructions.\"\n    },\n    {\n        \"question\": \"System software manages hardware and also what other type of software?\",\n        \"options\": {\n            \"A\": \"Utility software\",\n            \"B\": \"Application software\",\n            \"C\": \"Firmware\",\n            \"D\": \"Driver software\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"System software manages hardware and application software.\"\n    },\n    {\n        \"question\": \"What do the programs, data, and instructions of software enable a computer to do?\",\n        \"options\": {\n            \"A\": \"Generate heat\",\n            \"B\": \"Perform actions\",\n            \"C\": \"Store electricity\",\n            \"D\": \"Become physically larger\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"Software tells a computer what to do, which means it enables it to perform actions.\"\n    }\n]', '2026-05-19 07:55:33'),
(2, 'admin', 6, 2, 146, 'Software Engineering Principles MCQ', 'Source Text:\r\nSoftware is a collection of programs, data, and instructions that tell a computer what to do. System software manages hardware and application software helps users perform tasks.', '[\n    {\n        \"question\": \"According to the provided text, what fundamentally constitutes software?\",\n        \"options\": {\n            \"A\": \"Programs, data, and instructions\",\n            \"B\": \"Hardware components and operating systems\",\n            \"C\": \"Physical circuits and memory chips\",\n            \"D\": \"User interfaces and network protocols\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"The source defines software as \'a collection of programs, data, and instructions that tell a computer what to do\'.\"\n    },\n    {\n        \"question\": \"What is the primary role of software in a computer system?\",\n        \"options\": {\n            \"A\": \"To direct the computer\'s operations\",\n            \"B\": \"To physically store data permanently\",\n            \"C\": \"To provide electrical power to components\",\n            \"D\": \"To manufacture new hardware devices\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"Software\'s role is to \'tell a computer what to do,\' which means directing its operations.\"\n    },\n    {\n        \"question\": \"Which of the following is explicitly mentioned as a component of software?\",\n        \"options\": {\n            \"A\": \"Instructions\",\n            \"B\": \"Monitors\",\n            \"C\": \"Keyboards\",\n            \"D\": \"Printers\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"The source states software is a collection of \'programs, data, and instructions.\' Monitors, keyboards, and printers are hardware.\"\n    },\n    {\n        \"question\": \"What is the main function of system software?\",\n        \"options\": {\n            \"A\": \"To manage the computer\'s hardware\",\n            \"B\": \"To help users perform specific tasks\",\n            \"C\": \"To create new application programs\",\n            \"D\": \"To connect to the internet\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"The source explicitly states, \'System software manages hardware\'.\"\n    },\n    {\n        \"question\": \"What is the primary purpose of application software?\",\n        \"options\": {\n            \"A\": \"To assist users in performing specific tasks\",\n            \"B\": \"To control the internal components of a computer\",\n            \"C\": \"To maintain the computer\'s power supply\",\n            \"D\": \"To design new computer hardware\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"The source states, \'application software helps users perform tasks\'.\"\n    },\n    {\n        \"question\": \"How does system software differ from application software based on their primary roles?\",\n        \"options\": {\n            \"A\": \"System software manages hardware, while application software helps users perform tasks.\",\n            \"B\": \"System software is for entertainment, while application software is for work.\",\n            \"C\": \"System software is always free, while application software is always paid.\",\n            \"D\": \"System software runs on servers, while application software runs on desktops.\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"The source directly contrasts their roles: \'System software manages hardware and application software helps users perform tasks\'.\"\n    },\n    {\n        \"question\": \"A word processor, designed for writing documents, falls under which general category of software?\",\n        \"options\": {\n            \"A\": \"Application software\",\n            \"B\": \"System software\",\n            \"C\": \"Firmware\",\n            \"D\": \"Utility software\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"A word processor helps a user perform the task of writing documents, which aligns with the definition of application software.\"\n    },\n    {\n        \"question\": \"Which of the following is NOT considered a component of software?\",\n        \"options\": {\n            \"A\": \"Physical memory chips\",\n            \"B\": \"Programs\",\n            \"C\": \"Data\",\n            \"D\": \"Instructions\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"Programs, data, and instructions constitute software. Physical memory chips are hardware components.\"\n    },\n    {\n        \"question\": \"The \'instructions\' component of software primarily serves to:\",\n        \"options\": {\n            \"A\": \"Direct the computer\'s actions\",\n            \"B\": \"Physically store user files\",\n            \"C\": \"Generate electrical signals\",\n            \"D\": \"Display visual output\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"Software, including its instructions, is designed to \'tell a computer what to do,\' which means directing its actions.\"\n    },\n    {\n        \"question\": \"If a program is designed to manage the computer\'s file system, it would be categorized as:\",\n        \"options\": {\n            \"A\": \"System software\",\n            \"B\": \"Application software\",\n            \"C\": \"Utility software\",\n            \"D\": \"Firmware\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"Managing the file system is a core function related to managing the computer\'s hardware and resources, fitting the description of system software.\"\n    }\n]', '2026-05-19 07:59:09'),
(3, 'admin', 6, 2, 146, 'Software Engineering Principles MCQ', 'Source Text:\r\nSoftware is a collection of programs, data, and instructions that tell a computer what to do. System software manages hardware and application software helps users perform tasks.', '[\n    {\n        \"question\": \"According to the source text, what is software primarily defined as?\",\n        \"options\": {\n            \"A\": \"A collection of programs, data, and instructions.\",\n            \"B\": \"A network of interconnected computers.\",\n            \"C\": \"A collection of physical hardware components.\",\n            \"D\": \"A database management system only.\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"The source text defines software as \'a collection of programs, data, and instructions that tell a computer what to do\'.\"\n    },\n    {\n        \"question\": \"What is the fundamental role of software in relation to a computer?\",\n        \"options\": {\n            \"A\": \"To provide electrical power to the hardware.\",\n            \"B\": \"To physically assemble the computer parts.\",\n            \"C\": \"To store user-generated documents exclusively.\",\n            \"D\": \"To tell a computer what actions to perform.\"\n        },\n        \"correct\": \"D\",\n        \"explanation\": \"The source text states software \'tell a computer what to do\'.\"\n    },\n    {\n        \"question\": \"Which type of software is specifically responsible for managing computer hardware?\",\n        \"options\": {\n            \"A\": \"Application software.\",\n            \"B\": \"Utility software.\",\n            \"C\": \"System software.\",\n            \"D\": \"Productivity software.\"\n        },\n        \"correct\": \"C\",\n        \"explanation\": \"The source text specifies that \'System software manages hardware\'.\"\n    },\n    {\n        \"question\": \"What is the main purpose of application software?\",\n        \"options\": {\n            \"A\": \"To directly control the CPU\'s temperature.\",\n            \"B\": \"To connect to external power sources.\",\n            \"C\": \"To manage the computer\'s internal clock.\",\n            \"D\": \"To help users perform specific tasks.\"\n        },\n        \"correct\": \"D\",\n        \"explanation\": \"The source text states \'application software helps users perform tasks\'.\"\n    },\n    {\n        \"question\": \"Which of the following is NOT explicitly mentioned as a component of software in the definition provided?\",\n        \"options\": {\n            \"A\": \"Instructions.\",\n            \"B\": \"Programs.\",\n            \"C\": \"Physical circuits.\",\n            \"D\": \"Data.\"\n        },\n        \"correct\": \"C\",\n        \"explanation\": \"The definition includes \'programs, data, and instructions\', but not \'physical circuits\'.\"\n    },\n    {\n        \"question\": \"An operating system, which controls hardware resources, falls under which category of software?\",\n        \"options\": {\n            \"A\": \"System software.\",\n            \"B\": \"Application software.\",\n            \"C\": \"User software.\",\n            \"D\": \"Task software.\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"System software is defined as managing hardware, making an operating system a prime example.\"\n    },\n    {\n        \"question\": \"A word processor used to create documents is an example of what kind of software?\",\n        \"options\": {\n            \"A\": \"System software.\",\n            \"B\": \"Application software.\",\n            \"C\": \"Management software.\",\n            \"D\": \"Instructional software.\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"Application software helps users perform tasks, and creating documents with a word processor is a user task.\"\n    },\n    {\n        \"question\": \"What does the \'instructions\' component of software primarily do?\",\n        \"options\": {\n            \"A\": \"It provides the commands for the computer to execute.\",\n            \"B\": \"It records user input for later review.\",\n            \"C\": \"It generates random numbers for security.\",\n            \"D\": \"It physically stores the computer\'s memory.\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"Software\'s role is to \'tell a computer what to do\', which is achieved through instructions.\"\n    },\n    {\n        \"question\": \"If software \'tells a computer what to do\', what is the computer\'s role in this interaction?\",\n        \"options\": {\n            \"A\": \"To manage the software\'s development.\",\n            \"B\": \"To create new software autonomously.\",\n            \"C\": \"To execute the commands provided by the software.\",\n            \"D\": \"To independently decide its actions.\"\n        },\n        \"correct\": \"C\",\n        \"explanation\": \"The computer follows the instructions given by the software, thus executing its commands.\"\n    },\n    {\n        \"question\": \"Which statement accurately distinguishes system software from application software based on the provided text?\",\n        \"options\": {\n            \"A\": \"System software is for entertainment, application software is for work.\",\n            \"B\": \"System software manages hardware, while application software helps users perform tasks.\",\n            \"C\": \"System software is always free, application software is always paid.\",\n            \"D\": \"System software performs tasks, while application software manages hardware.\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"The text clearly states \'System software manages hardware and application software helps users perform tasks\'.\"\n    }\n]', '2026-05-19 08:23:08'),
(4, 'admin', 6, 2, 138, 'Fundamentals of Computing and Digital Systems MCQ', '', '[\n    {\n        \"question\": \"Which component is considered the \'brain\' of the computer, responsible for executing instructions and performing calculations?\",\n        \"options\": {\n            \"A\": \"Hard Disk Drive (HDD)\",\n            \"B\": \"Central Processing Unit (CPU)\",\n            \"C\": \"Random Access Memory (RAM)\",\n            \"D\": \"Graphics Processing Unit (GPU)\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"The CPU (Central Processing Unit) is responsible for interpreting and executing most of the commands from the computer\'s hardware and software.\"\n    },\n    {\n        \"question\": \"What is the primary function of an operating system (OS)?\",\n        \"options\": {\n            \"A\": \"To browse the internet\",\n            \"B\": \"To create and edit documents\",\n            \"C\": \"To play video games\",\n            \"D\": \"To manage computer hardware and software resources\"\n        },\n        \"correct\": \"D\",\n        \"explanation\": \"An operating system manages all of the computer\'s hardware and software, providing a platform for other programs to run.\"\n    },\n    {\n        \"question\": \"Which of the following is an example of an input device?\",\n        \"options\": {\n            \"A\": \"Monitor\",\n            \"B\": \"Speakers\",\n            \"C\": \"Printer\",\n            \"D\": \"Keyboard\"\n        },\n        \"correct\": \"D\",\n        \"explanation\": \"A keyboard is an input device used to enter text, characters, and other commands into a computer or similar device.\"\n    },\n    {\n        \"question\": \"What does RAM stand for in the context of computer memory?\",\n        \"options\": {\n            \"A\": \"Remote Access Module\",\n            \"B\": \"Read-Only Memory\",\n            \"C\": \"Random Access Memory\",\n            \"D\": \"Rapid Application Method\"\n        },\n        \"correct\": \"C\",\n        \"explanation\": \"RAM (Random Access Memory) is a form of computer memory that can be read and changed in any order, typically used to store working data and machine code.\"\n    },\n    {\n        \"question\": \"What is the smallest unit of data in a computer?\",\n        \"options\": {\n            \"A\": \"Megabyte\",\n            \"B\": \"Kilobyte\",\n            \"C\": \"Byte\",\n            \"D\": \"Bit\"\n        },\n        \"correct\": \"D\",\n        \"explanation\": \"A bit (binary digit) is the most basic unit of information in computing and digital communications, representing a logical state with one of two possible values, typically 0 or 1.\"\n    },\n    {\n        \"question\": \"Which type of software is designed to perform specific tasks for the user, such as word processing or web browsing?\",\n        \"options\": {\n            \"A\": \"Firmware\",\n            \"B\": \"Utility software\",\n            \"C\": \"System software\",\n            \"D\": \"Application software\"\n        },\n        \"correct\": \"D\",\n        \"explanation\": \"Application software (or app) is a computer program designed to perform a specific task or function directly for the user or for another application program.\"\n    },\n    {\n        \"question\": \"The binary number system uses how many distinct digits?\",\n        \"options\": {\n            \"A\": \"Two\",\n            \"B\": \"Sixteen\",\n            \"C\": \"Eight\",\n            \"D\": \"Ten\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"The binary number system uses only two distinct digits, 0 and 1, to represent all numbers.\"\n    },\n    {\n        \"question\": \"Which of the following is a non-volatile memory type, meaning it retains its data even when power is turned off?\",\n        \"options\": {\n            \"A\": \"RAM\",\n            \"B\": \"ROM\",\n            \"C\": \"Cache Memory\",\n            \"D\": \"Registers\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"ROM (Read-Only Memory) is a type of non-volatile memory used in computers and other electronic devices. Data stored in ROM cannot be electronically modified after the manufacture of the memory device.\"\n    },\n    {\n        \"question\": \"What is the purpose of a computer network?\",\n        \"options\": {\n            \"A\": \"To allow computers to share resources and data\",\n            \"B\": \"To increase the processing speed of a single computer\",\n            \"C\": \"To physically protect computer hardware\",\n            \"D\": \"To convert analog signals to digital signals\"\n        },\n        \"correct\": \"A\",\n        \"explanation\": \"A computer network allows multiple computers and devices to connect and share resources, such as files, printers, and internet access.\"\n    },\n    {\n        \"question\": \"Which term describes the physical components of a computer system?\",\n        \"options\": {\n            \"A\": \"Software\",\n            \"B\": \"Hardware\",\n            \"C\": \"Firmware\",\n            \"D\": \"Operating System\"\n        },\n        \"correct\": \"B\",\n        \"explanation\": \"Hardware refers to the physical components of a computer system, such as the CPU, memory, and storage devices.\"\n    }\n]', '2026-05-26 07:27:24');
