INSERT INTO `rms_email_templates` (`id`, `template_key`, `template_name`, `subject`, `body_html`, `is_enabled`, `updated_at`, `created_at`) VALUES
(1, 'registration_confirmation', 'Registration Confirmation', 'Welcome to Eden Campus - Registration Confirmation', '<h2>Welcome {{student_name}}</h2>\r\n     <p>Your registration has been completed successfully.</p>\r\n     <p><strong>Registration No:</strong> {{reg_no}}</p>\r\n     <p><strong>Course:</strong> {{course_name}}</p>\r\n     <p><strong>Batch:</strong> {{batch_name}}</p>\r\n     <p>Thank you,<br>Eden Campus</p>', 0, '2026-05-24 08:28:15', '2026-05-20 18:07:25'),
(2, 'payment_receipt', 'Payment Receipt', 'Payment Receipt - {{receipt_no}}', '<h2>Payment Receipt</h2>\r\n     <p>Dear {{student_name}},</p>\r\n     <p>We have received your payment.</p>\r\n     <p><strong>Receipt No:</strong> {{receipt_no}}</p>\r\n     <p><strong>Amount:</strong> {{amount}}</p>\r\n     <p><strong>Payment Date:</strong> {{payment_date}}</p>\r\n     <p><strong>Balance:</strong> {{balance}}</p>\r\n     <p>Thank you,<br>Eden Campus</p>', 0, '2026-05-20 18:36:32', '2026-05-20 18:07:25'),
(3, 'fee_due_reminder', 'Fee Due Reminder', 'Fee Reminder - Eden Campus', '<h2>Fee Reminder</h2>\r\n     <p>Dear {{student_name}},</p>\r\n     <p>This is a reminder that your course fee payment is due.</p>\r\n     <p><strong>Due Amount:</strong> {{due_amount}}</p>\r\n     <p><strong>Due Date:</strong> {{due_date}}</p>\r\n     <p>Please make the payment on or before the due date.</p>\r\n     <p>Thank you,<br>Eden Campus</p>', 0, '2026-05-20 18:36:32', '2026-05-20 18:07:25'),
(4, 'overdue_reminder', 'Overdue Reminder', 'Overdue Payment Reminder - Eden Campus', '<h2>Overdue Payment Reminder</h2>\r\n     <p>Dear {{student_name}},</p>\r\n     <p>Your payment is overdue.</p>\r\n     <p><strong>Overdue Amount:</strong> {{overdue_amount}}</p>\r\n     <p><strong>Due Date:</strong> {{due_date}}</p>\r\n     <p>Please settle the payment as soon as possible.</p>\r\n     <p>Thank you,<br>Eden Campus</p>', 0, '2026-05-20 18:36:32', '2026-05-20 18:07:25'),
(5, 'marks_result_release', 'Marks / Results Released', 'Your Results Have Been Released - Eden Campus', '<h2>Results Released</h2>\r\n     <p>Dear {{student_name}},</p>\r\n     <p>Your marks/results have been released.</p>\r\n     <p><strong>Course:</strong> {{course_name}}</p>\r\n     <p><strong>Module:</strong> {{module_name}}</p>\r\n     <p><strong>Marks:</strong> {{marks}}</p>\r\n     <p><strong>Grade:</strong> {{grade}}</p>\r\n     <p>Thank you,<br>Eden Campus</p>', 0, '2026-05-20 18:36:32', '2026-05-20 18:07:25'),
(405, 'academic_progress_updated', 'Academic Progress Updated', 'Academic Progress Updated - Eden Campus', '<h2>Academic Progress Updated</h2><p>Dear {{student_name}}, your academic progress has been updated.</p>', 0, '2026-05-24 08:28:04', '2026-05-24 08:03:52'),
(406, 'batch_transferred', 'Batch Transfer Notification', 'Batch Transfer - Eden Campus', '<h2>Batch Transfer</h2><p>Dear {{student_name}}, your batch has been updated.</p>', 0, '2026-05-24 08:28:04', '2026-05-24 08:03:52');
