INSERT INTO `whatsapp_templates` (`id`, `template_key`, `title`, `is_enabled`, `message`, `created_at`, `updated_at`, `template_name`, `message_body`) VALUES
(1, 'registration_confirmation', 'Registration Confirmation', 0, 'Hello {{student_name}}, your registration is completed.\r\n\r\nStudent ID: {{student_id}}\r\nReference No: {{reference_no}}\r\nCenter Reg No: {{center_reg_no}}\r\nAcademic Email: {{academic_email}}\r\nPassword: {{academic_password}}\r\n\r\nCourse: {{course_name}}\r\n\r\nThank you,\r\nEDEN CAMPUS', '2026-05-21 07:53:58', '2026-05-21 12:57:21', 'Registration Confirmation', 'Hello {{student_name}}, your registration has been completed successfully.\r\n\r\nStudent ID: {{student_id}}\r\nReference No: {{reference_no}}\r\nCenter Reg No: {{center_reg_no}}\r\nAcademic Email: {{academic_email}}\r\nPassword: {{academic_password}}\r\nExisting Student: {{is_existing}}\r\n\r\nCourse References:\r\n{{course_references_text}}\r\n\r\nThank you,\r\nEDEN CAMPUS'),
(2, 'payment_receipt', 'Payment Confirmation', 0, 'Hello {{student_name}}, payment received successfully.\r\n\r\nReceipt No: {{receipt_no}}\r\nAmount: LKR {{amount}}\r\nDate: {{date_paid}}\r\nBalance: LKR {{balance}}\r\n\r\nThank you,\r\nEDEN CAMPUS', '2026-05-21 07:53:58', '2026-05-24 08:16:19', 'Payment Receipt', 'Hello {{student_name}}, payment received successfully.\r\n\r\nRegistration No: {{reg_no}}\r\nReceipt No: {{receipt_no}}\r\nAmount: LKR {{amount}}\r\nPayment Date: {{payment_date}}\r\nBalance: {{balance}}\r\n\r\nThank you,\r\nEDEN CAMPUS'),
(3, 'fee_due_reminder', 'Fee Due Reminder', 0, 'Hello {{student_name}}, this is a reminder for your upcoming fee payment.\r\n\r\nDue Amount: LKR {{due_amount}}\r\nDue Date: {{due_date}}\r\n\r\nPlease make the payment on time.\r\nEDEN CAMPUS', '2026-05-21 07:53:58', '2026-05-21 12:57:38', 'Fee Due Reminder', 'Hello {{student_name}}, this is a reminder that your course fee payment is due.\r\n\r\nDue Amount: LKR {{due_amount}}\r\nDue Date: {{due_date}}\r\n\r\nPlease make the payment on or before the due date.\r\nEDEN CAMPUS'),
(4, 'overdue_reminder', 'Overdue Reminder', 0, 'Hello {{student_name}}, your fee payment is overdue.\r\n\r\nOverdue Amount: LKR {{overdue_amount}}\r\nDue Date: {{due_date}}\r\n\r\nPlease contact accounts department.\r\nEDEN CAMPUS', '2026-05-21 07:53:58', '2026-05-21 12:57:38', 'Overdue Reminder', 'Hello {{student_name}}, your payment is overdue.\r\n\r\nOverdue Amount: LKR {{overdue_amount}}\r\nDue Date: {{due_date}}\r\n\r\nPlease settle the payment as soon as possible.\r\nEDEN CAMPUS'),
(5, 'marks_result_release', 'Marks / Results Release', 0, 'Hello {{student_name}}, your results have been released.\r\n\r\nCourse: {{course_name}}\r\nModule/Exam: {{exam_name}}\r\nResult: {{result}}\r\n\r\nPlease login to view more details.\r\nEDEN CAMPUS', '2026-05-21 07:53:58', '2026-05-21 12:57:38', 'Marks / Results Released', 'Hello {{student_name}}, your marks/results have been released.\r\n\r\nCourse: {{course_name}}\r\nModule: {{module_name}}\r\nMarks: {{marks}}\r\nGrade: {{grade}}\r\n\r\nPlease login to view more details.\r\nEDEN CAMPUS'),
(150, 'academic_progress_updated', '', 0, '', '2026-05-24 08:03:52', '2026-05-24 08:16:19', 'Academic Progress Updated', 'Hello {{student_name}}, your academic progress has been updated.\r\nEDEN CAMPUS'),
(151, 'batch_transferred', '', 0, '', '2026-05-24 08:03:52', '2026-05-24 08:16:19', 'Batch Transfer Notification', 'Hello {{student_name}}, your batch has been updated.\r\nEDEN CAMPUS');
