--
-- Triggers `lms_submissions`
--
DELIMITER $$
CREATE TRIGGER `trg_submissions_gradebook_upd` AFTER UPDATE ON `lms_submissions` FOR EACH ROW BEGIN
  IF NEW.workflow_status IN ('approved','released') THEN
    VALUES (
      NEW.student_id,
      (SELECT course_id FROM lms_assessments WHERE id=NEW.assessment_id),
      NEW.batch_id,
      NEW.assessment_id,
      COALESCE(NEW.final_score, NEW.provisional_score, NEW.score),
      (SELECT max_score FROM lms_assessments WHERE id=NEW.assessment_id),
      1, NOW()
    )
    ON DUPLICATE KEY UPDATE score=VALUES(score), max_score=VALUES(max_score), updated_at=NOW();
  END IF;
END
$$
DELIMITER ;

