--
-- Structure for view `vw_due_report`
--
DROP TABLE IF EXISTS `vw_due_report`;

CREATE ALGORITHM=UNDEFINED DEFINER=`edencamp`@`localhost` SQL SECURITY INVOKER VIEW `vw_due_report`  AS SELECT `ps`.`student_id` AS `student_id`, `s`.`name` AS `student_name`, `ps`.`installment_no` AS `installment_no`, `ps`.`due_date` AS `due_date`, coalesce(`ps`.`course_fee_lkr`,0) + coalesce(`ps`.`registration_fee_lkr`,0) AS `due_lkr`, coalesce((select sum(`p2`.`amount`) from `payments` `p2` where `p2`.`student_id` = `ps`.`student_id` and cast(`p2`.`date_paid` as date) <= `ps`.`due_date`),0) AS `paid_upto_due_lkr`, greatest(coalesce(`ps`.`course_fee_lkr`,0) + coalesce(`ps`.`registration_fee_lkr`,0) - coalesce((select sum(`p2`.`amount`) from `payments` `p2` where `p2`.`student_id` = `ps`.`student_id` and cast(`p2`.`date_paid` as date) <= `ps`.`due_date`),0),0) AS `outstanding_lkr` FROM (`payment_schedule` `ps` left join `students` `s` on(`s`.`id` = `ps`.`student_id`)) ;

